class O{char[][]G;int r,c,d,u,v;String s(boolean p,String[]s){int k=0;for(;!s[k].isEmpty();k++);G=new char[k][];for(int i=0;i<k;i++){var a=p?s[i]:s[i].replace("#","##").replace("O","[]").replace(".","..").replace("@","@.");G[i]=a.toCharArray();for(int j=0;j<G[i].length;j++)if(G[i][j]==64){r=i;c=j;G[i][j]=46;}}for(;k<s.length;k++)for(var z:s[k].toCharArray()){d="^v<>".indexOf(z);u=d<2?d*2-1:0;v=d>1?d*2-5:0;if(f(r+u,c+v,0))f(r+=u,c+=v,1);}long n=0;for(int i=0;i<G.length;i++)for(int j=0;j<G[i].length;j++)if(G[i][j]%12==7)n+=i*100L+j;return n+"";}boolean f(int i,int j,int m){var x=G[i][j];if(x<36)return 1<0;if(x<47)return 1>0;int a=i+u,b=j+v;if(x<91|d>1){if(!f(a,b,m))return 1<0;if(m>0){G[a][b]=x;G[i][j]=46;}return 1>0;}if(x>91)j--;if(!f(i+u,j,m)||!f(i+u,j+1,m))return 1<0;if(m>0){G[i+u][j]=91;G[i+u][j+1]=93;G[i][j]=G[i][j+1]=46;}return 1>0;}}
